import React from 'react';
import LandingForm from '../components/LandingForm';

const LandingPage = () => (
  <div className="landing-page">
    <h1>Landing Page Của Bạn</h1>
    <p>Đăng ký để nhận tư vấn miễn phí!</p>
    <LandingForm />
  </div>
);

export default LandingPage;
